__NUXT_JSONP__("/finanzas-publicas/columnas", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o){return {data:[{columnas:[{slug:"un_escenario_incompleto_del_bienestar_la_salud_y_la_educacion_en_el_presupuesto_2026",title:"Un escenario incompleto del bienestar: la salud y la educación en el presupuesto 2026",date:"2025-09-25T20:14:56.678Z",img:"https:\u002F\u002Fucarecdn.com\u002F91bd1518-6bb5-4f13-a05a-a8a61ec04d1d\u002F","img-alt":"Presupuesto salud y educación",autor:g,medio:e,link:"https:\u002F\u002Fanimalpolitico.com\u002Fanalisis\u002Finvitades\u002Fun-escenario-incompleto-del-bienestar-la-salud-y-la-educacion-en-el-presupuesto-2026",category:a,extracto:"El presupuesto para salud en 2026 refuerza la atención para quienes ya están cubiertos, pero deja vulnerable a la población más desprotegida, mientras que en educación la inversión se concentra en transferencias directas a los estudiantes, sin atender la calidad educativa o la infraestructura escolar.",toc:[{id:"salud-crecimiento-o-desequilibrio",depth:d,text:"Salud: ¿crecimiento o desequilibrio?"},{id:"educación-un-embudo-que-deja-a-muchos-fuera",depth:d,text:"Educación: un embudo que deja a muchos fuera"}],dir:b,path:"\u002Fcolumnas\u002Fun_escenario_incompleto_del_bienestar_la_salud_y_la_educacion_en_el_presupuesto_2026",extension:c,createdAt:h,updatedAt:h},{slug:"primero_la_politica_el_pago_de_la_deuda_vendra_despues",title:"Primero la política, el pago de la deuda vendrá después",date:"2025-09-18T16:42:40.019Z",img:"https:\u002F\u002Fucarecdn.com\u002Fd0f221c1-3e5e-478b-8849-f9e3abac4d7d\u002F","img-alt":"Deuda pública",autor:i,medio:f,link:"https:\u002F\u002Fwww.eleconomista.com.mx\u002Fopinion\u002Fprimero-politica-pago-deuda-vendra-20250918-777717.html",category:a,extracto:"Es necesario replantear nuestro gasto para atender adecuadamente las necesidades actuales de la población en materia de salud, educación, seguridad, entre otros ámbitos, por encima del deseo que tiene el gobierno de mantenerse en el poder.",toc:[],dir:b,path:"\u002Fcolumnas\u002Fprimero_la_politica_el_pago_de_la_deuda_vendra_despues",extension:c,createdAt:j,updatedAt:j},{slug:"radiografia_de_las_donaciones_en_mexico",title:"Radiografía de las donaciones en México",date:"2025-08-27T17:32:43.454Z",img:"https:\u002F\u002Fucarecdn.com\u002F91b847e0-cc0e-402c-b694-1cf05211d619\u002F",autor:"Liliana Alvarado",medio:f,link:"https:\u002F\u002Fwww.eleconomista.com.mx\u002Fopinion\u002Fradiografia-donaciones-mexico-20250827-774501.html?fbclid=IwY2xjawMit_tleHRuA2FlbQIxMABicmlkETE3VGdkRm80Q2lEcVlGMWE3AR5vjzDGaa6eoPagMSe4l8eFLqTIQpNBSWLzzu7BBj8AqwW2P1fB3MY9zkVL-g_aem_j2IC7UQhE8K2JCGNAzMt0g",category:a,extracto:"El donativo en México se concentra en instituciones asistenciales, mientras que el apoyo a investigación científica o tecnológica disminuye. Esto refleja un interés en atender necesidades inmediatas más que en solucionar problemas estructurales de manera sostenible.",toc:[],dir:b,path:"\u002Fcolumnas\u002Fradiografia_de_las_donaciones_en_mexico",extension:c,createdAt:"2025-11-25T01:24:03.246Z",updatedAt:"2025-11-25T01:24:03.247Z"},{slug:"el_costo_de_la_austeridad_recortes_que_afectan_el_bienestar",title:"El costo de la austeridad: recortes que afectan el bienestar",date:"2025-08-12T21:27:22.487Z",img:"https:\u002F\u002Fucarecdn.com\u002F76e1c68a-014b-4426-8dce-4b86c31cbb61\u002F",autor:g,medio:e,link:"https:\u002F\u002Fanimalpolitico.com\u002Fanalisis\u002Finvitades\u002Fcosto-austeridad-recortes-bienestar",category:a,extracto:"Un programa de educación que no gasta a tiempo sus recursos no puede construir escuelas ni equiparlas. Un programa de salud que no ejerce su presupuesto no puede brindar atención ni comprar medicinas o equipo médico. El retraso y recorte en el gasto es un obstáculo real que impide que los objetivos de desarrollo y bienestar se cumplan.",toc:[{id:"menor-gasto-en-áreas-clave",depth:d,text:"Menor gasto en áreas clave"},{id:"los-más-vulnerables-los-más-afectados",depth:d,text:"Los más vulnerables, los más afectados"},{id:"anticorrupción-y-medio-ambiente-en-pausa",depth:d,text:"Anticorrupción y medio ambiente, en pausa"},{id:"la-urgencia-de-gastar-bien",depth:d,text:"La urgencia de gastar bien"}],dir:b,path:"\u002Fcolumnas\u002Fel_costo_de_la_austeridad_recortes_que_afectan_el_bienestar",extension:c,createdAt:k,updatedAt:k},{slug:"tarifas_y_cobro_de_agua_en_la_cdmx_nuestra_relacion_con_el_agua_a_traves_de_lo_que_pagamos",title:"Tarifas y cobro de agua en la CDMX: nuestra relación con el agua a través de lo que pagamos",date:"2025-08-01T19:21:32.477Z",img:"https:\u002F\u002Fucarecdn.com\u002Ff8b34950-2489-4945-8c60-4df75fdfb2ac\u002F",autor:"Agustín Castillo",medio:e,link:"https:\u002F\u002Fanimalpolitico.com\u002Fanalisis\u002Finvitades\u002Ftarifas-y-cobro-agua-cdmx",category:a,extracto:"¿Cuánto se paga de agua en la CDMX? De acuerdo con un estudio de la UAM, los subsidios no benefician prioritariamente a la población con menores recursos y las tarifas artificialmente bajas generan una menor recaudación, provocan distorsiones en el mercado y no contribuyen a reducir el consumo excesivo.",toc:[],dir:b,path:"\u002Fcolumnas\u002Ftarifas_y_cobro_de_agua_en_la_cdmx_nuestra_relacion_con_el_agua_a_traves_de_lo_que_pagamos",extension:c,createdAt:l,updatedAt:l},{slug:"franeleros_extorsion_normalizada",title:"Franeleros: extorsión normalizada",date:"2025-07-18T19:54:28.324Z",img:"https:\u002F\u002Fucarecdn.com\u002F74b3a215-6a2c-4f9f-ba40-428de1dafaee\u002F",autor:"Emiliano Montes de Oca",medio:e,link:"https:\u002F\u002Fanimalpolitico.com\u002Fanalisis\u002Finvitades\u002Ffraneleros-extorsion-normalizada",category:a,extracto:"Ante la omisión de autoridades y la normalización social, los franeleros se han adueñado del espacio público en la CDMX, extorsionando a automovilistas con total impunidad. Aunque el gobierno capitalino propone endurecer sanciones y ofrecer alternativas de empleo, sin una aplicación real de esas políticas, la calle seguirá siendo rehén de intereses privados.",toc:[],dir:b,path:"\u002Fcolumnas\u002Ffraneleros_extorsion_normalizada",extension:c,createdAt:m,updatedAt:m},{slug:"deuda_publica_la_herencia_incomoda_de_amlo",title:"Deuda pública: la herencia incómoda de AMLO",date:"2025-07-15T16:43:30.718Z",img:"https:\u002F\u002Fucarecdn.com\u002Fb7657db4-8451-4cd5-9c79-3d14bd1d0336\u002F","img-alt":"México deuda",autor:i,medio:f,link:"https:\u002F\u002Fwww.eleconomista.com.mx\u002Fopinion\u002Fdeuda-publica-herencia-incomoda-amlo-20250714-768146.html",category:a,extracto:"El compromiso de reducir el endeudamiento en este año no debe equipararse a una buena intención, tiene que abordarse como una necesidad estructural de la que depende la estabilidad financiera del país.",toc:[],dir:b,path:"\u002Fcolumnas\u002Fdeuda_publica_la_herencia_incomoda_de_amlo",extension:c,createdAt:n,updatedAt:n},{slug:"el_futuro_de_los_datos_abiertos_en_mexico",title:"El futuro de los datos abiertos en México",date:"2025-06-13T22:13:57.595Z",img:"https:\u002F\u002Fucarecdn.com\u002Fef67a276-a054-455c-a248-61733c2ba474\u002F",autor:"Dalia Toledo",medio:"La Lista",link:"https:\u002F\u002Fla-lista.com\u002Fopinion\u002Fel-futuro-de-los-datos-abiertos-en-mexico#google_vignette",category:a,extracto:"Como sociedad civil tenemos la obligación de ser un actor vigilante que asegure que la apertura de los datos camine hacia un modelo de gobierno más abierto, transparente, y útil para las personas.",toc:[],dir:b,path:"\u002Fcolumnas\u002Fel_futuro_de_los_datos_abiertos_en_mexico",extension:c,createdAt:o,updatedAt:o}],total:[{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{}]}],fetch:{},mutations:[]}}("finanzas-publicas","\u002Fcolumnas",".md",3,"Animal Político","El Economista","Mireya Mondragón","2025-11-25T01:24:03.250Z","Liliana Alvarado ","2025-11-25T01:24:03.245Z","2025-11-25T01:24:03.236Z","2025-11-25T01:24:03.249Z","2025-11-25T01:24:03.241Z","2025-11-25T01:24:03.235Z","2025-11-25T01:24:03.238Z")));